from copy import deepcopy


class PartsCounter:
    def __init__(self, catalog):
        if not isinstance(catalog, dict):
            raise TypeError("catalog must be a dictionary")
        for part_id, entry in catalog.items():
            if not isinstance(part_id, str):
                raise TypeError("part IDs must be strings")
            if not part_id:
                raise ValueError("part IDs must be nonempty")
            if not isinstance(entry, dict):
                raise TypeError("catalog entries must be dictionaries")
            if set(entry) != {"unit_cost", "available"}:
                raise ValueError("invalid catalog entry")
            for value in entry.values():
                if not isinstance(value, int) or isinstance(value, bool):
                    raise TypeError("catalog values must be integers")
                if value < 0:
                    raise ValueError("catalog values must be nonnegative")
        self._catalog = deepcopy(catalog)
        self._basket = {}
        self._next_id = 1

    def item(self, part_id):
        if part_id not in self._catalog:
            raise KeyError(part_id)
        return deepcopy(self._catalog[part_id])

    def set_quantity(self, part_id, quantity):
        if part_id not in self._catalog:
            raise KeyError(part_id)
        if not isinstance(quantity, int) or isinstance(quantity, bool):
            raise TypeError("quantity must be an integer")
        if quantity < 0:
            raise ValueError("quantity must be nonnegative")
        if quantity > self._catalog[part_id]["available"]:
            raise ValueError("insufficient availability")
        if quantity == 0:
            self._basket.pop(part_id, None)
        else:
            self._basket[part_id] = quantity
        self._basket = {
            catalog_id: self._basket[catalog_id]
            for catalog_id in self._catalog
            if catalog_id in self._basket
        }

    def basket(self):
        total = sum(
            self._catalog[part_id]["unit_cost"] * quantity
            for part_id, quantity in self._basket.items()
        )
        return {"items": self._basket, "total": total}

    def commit(self):
        if not self._basket:
            raise ValueError("basket is empty")
        for part_id, quantity in self._basket.items():
            if quantity > self._catalog[part_id]["available"]:
                raise ValueError("insufficient availability")
        summary = self.basket()
        for part_id, quantity in self._basket.items():
            self._catalog[part_id]["available"] -= quantity
        reservation = {
            "reservation_id": f"q{self._next_id}",
            "items": summary["items"],
            "total": summary["total"],
        }
        self._next_id += 1
        self._basket.clear()
        return deepcopy(reservation)

